/* FitFirst V2 (forked from V1, restyled by the Atelier system) — the counter: FitFirst Billing (POS path B), sales register, returns & exchanges, GST, exports, day close */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$, R = FF.ROLES;
  const docType = () => ({ REGULAR: 'TAX_INVOICE', COMPOSITION: 'BILL_OF_SUPPLY', NONE: 'RECEIPT' }[FF.store().reg]);
  const fresh = () => ({ lines: [], visit: null, cust: { name: '', phone: '', gstin: '' }, q: '', credit: 0, creditNo: '' });
  let B = fresh();
  const addLine = (p, size, rec) => { size = size && p.stock[size] > 0 ? size : Object.keys(p.stock).find((s) => p.stock[s] > 0); if (!size) return FF.toast(p.name + ' is out of stock', 'bad'); const ex = B.lines.find((l) => l.pid === p.id && l.size === size); if (ex) { if (ex.qty >= p.stock[size]) return FF.toast('Only ' + p.stock[size] + ' in stock', 'bad'); ex.qty++; } else B.lines.push({ pid: p.id, name: p.name, size, qty: 1, price: p.price, mrp: p.mrp, disc: 0, rec: !!rec }); };

  FF.page('billing', { title: 'Billing counter', icon: 'bill', roles: R.FLOOR, render: (code) => {
    if (code && B.visit !== code && FF.db.visits.some((v) => v.code === code)) loadVisit(code, true);
    const tt = FF.totals(B.lines), due = Math.max(0, tt.total - B.credit), s = FF.db.settings, q = B.q.toLowerCase(), res = q.length >= 2 ? FF.db.products.filter((p) => p.status === 'LIVE' && (p.name + ' ' + p.id + ' ' + p.barcode).toLowerCase().includes(q)).slice(0, 6) : [];
    return `<div class="ph1"><div><h1>Billing counter</h1><p>${FF.docName(docType())} · series <span class="mono">${s.billing.series}/26-27</span> · next no. <span class="mono">${String(s.billing.next).padStart(5, '0')}</span>${s.flags.offline ? ' · ' + U.badge('Offline — will sync', 'warn') : ''}</p></div><div class="row wrap">${FF.db.held.length ? `<button class="btn" data-act="b-recall">${FF.icon('clock')} Held bills · ${FF.db.held.length}</button>` : ''}<button class="btn" data-act="b-scan">${FF.icon('qr')} Scan shopper's FitFirst QR</button></div></div>
      <div class="pos"><div><div class="card"><div class="row"><span>${FF.icon('scan')}</span><input type="search" placeholder="Scan a barcode, or type a name or style code" value="${esc(B.q)}" data-change="b-q" id="b-q" aria-label="Scan or search" autocomplete="off"></div>
        ${res.length ? `<div class="mt8">${res.map((p) => `<button class="row btn-block" style="border:0;background:none;padding:8px 4px;border-bottom:1px solid var(--line);text-align:left" data-act="b-add" data-pid="${p.id}"><div class="thumb">${FF.garment(p)}</div><span class="grow"><b>${esc(p.name)}</b><br><span class="small muted mono">${p.id}</span></span>${U.sizes(p)}<b class="num">${FF.inr(p.price)}</b></button>`).join('')}</div>` : q.length >= 2 ? `<p class="small muted mt8">No live piece matches “${esc(B.q)}”.</p>` : `<p class="small muted mt8">USB and Bluetooth scanners type like a keyboard — just scan. Try <button class="link" data-act="b-demo">a sample scan</button>.</p>`}</div>
        ${B.visit ? `<div class="note n-ok mt12 row"><span class="grow">Linked to FitFirst visit <b class="code">${B.visit}</b> — this sale is attributed automatically.</span><button class="btn btn-s" data-act="b-unlink">Unlink</button></div>` : ''}
        <div class="card mt12"><div class="row between"><h3>Bill</h3><span class="small muted">${FF.sum(B.lines, (l) => l.qty)} pieces</span></div>${B.lines.map((l, i) => { const p = FF.prod(l.pid), g = FF.gstLine(l); return `<div class="cline"><div class="thumb">${FF.garment(p)}</div><div><b>${esc(l.name)}</b> ${l.rec ? U.badge('Recommended', 'ok') : ''}<div class="row wrap gap6 mt4"><select data-change="b-size" data-i="${i}" style="width:auto;min-height:30px;padding:2px 6px" aria-label="Size">${Object.entries(p.stock).map(([sz, n]) => `<option value="${sz}" ${sz === l.size ? 'selected' : ''} ${n <= 0 ? 'disabled' : ''}>${sz}</option>`).join('')}</select><span class="qty"><button data-act="b-qty" data-i="${i}" data-d="-1" aria-label="Less">−</button><span>${l.qty}</span><button data-act="b-qty" data-i="${i}" data-d="1" aria-label="More">+</button></span><button class="btn btn-s btn-g" data-act="b-disc" data-i="${i}">${l.disc ? '− ' + FF.inr(l.disc) + ' discount' : 'Discount'}</button></div><div class="tiny muted mt4">MRP ${FF.inr(l.mrp)} · HSN ${g.hsn} · GST ${g.rate}%${g.rate === 5 && l.price > 2500 && !/^5/.test(g.hsn) ? ' (drops to 5% because the price after discount is ₹2,500 or less)' : ''}</div></div><div class="right"><b class="num">${FF.inr(g.gross)}</b><br><button class="x" style="margin-left:auto" data-act="b-del" data-i="${i}" aria-label="Remove">${FF.icon('trash')}</button></div></div>`; }).join('') || U.empty('bill', 'Scan the first piece', 'Or scan the shopper’s FitFirst QR to pull in what they chose.')}</div>
        <div class="card mt12"><div class="row between"><h3>Customer <span class="small muted" style="font-weight:400">optional</span></h3></div><div class="grid g3 mt8">${U.field('Name', `<input data-change="b-cust" data-k="name" value="${esc(B.cust.name)}">`)}${U.field('Mobile (for WhatsApp e-bill)', `<input type="tel" maxlength="10" data-change="b-cust" data-k="phone" value="${esc(B.cust.phone)}">`)}${U.field('GSTIN (business customer)', `<input data-change="b-cust" data-k="gstin" maxlength="15" value="${esc(B.cust.gstin)}" style="text-transform:uppercase">`)}</div></div></div>
      <div class="cart card"><h3>Total</h3><dl class="kv mt12" style="grid-template-columns:1fr max-content"><dt>Subtotal</dt><dd class="num right">${FF.inr(tt.sub)}</dd>${tt.disc ? `<dt>Discounts</dt><dd class="num right">− ${FF.inr(tt.disc)}</dd>` : ''}${docType() === 'TAX_INVOICE' ? Object.entries(tt.by).map(([r, v]) => `<dt>GST ${r}% <span class="tiny">(included)</span></dt><dd class="num right">${FF.inr(v.tax)}</dd>`).join('') : ''}${B.credit ? `<dt>Credit note ${esc(B.creditNo)}</dt><dd class="num right">− ${FF.inr(B.credit)}</dd>` : ''}</dl><hr><div class="row between"><span class="muted">To pay</span><span class="serif num" style="font-size:34px">${FF.inr(due)}</span></div>
        <div class="grid g2 mt16" style="gap:8px">${[['CASH', 'cash', 'Cash'], ['UPI', 'qr', 'UPI QR'], ['CARD', 'bill', 'Card'], ['SPLIT', 'layers', 'Split']].map(([m, ic, l]) => `<button class="btn ${m === 'UPI' ? 'btn-p' : ''}" style="min-height:52px" data-act="b-pay" data-m="${m}" ${B.lines.length ? '' : 'disabled'}>${FF.icon(ic)} ${l}</button>`).join('')}</div><div class="row mt12"><button class="btn btn-g btn-s grow" data-act="b-hold" ${B.lines.length ? '' : 'disabled'}>Hold bill</button><button class="btn btn-g btn-s grow" data-act="b-clear" ${B.lines.length ? '' : 'disabled'}>Clear</button></div><p class="tiny muted mt12">Prices include GST. A bill cannot be edited after it is issued — corrections are made with a credit note.</p></div></div>`; },
    after: () => { const i = $('#b-q'); if (i && !$('.scrim') && window.innerWidth > 980) { i.focus(); i.setSelectionRange(B.q.length, B.q.length); } } });
  const loadVisit = (code, silent) => { const v = FF.db.visits.find((x) => x.code === code); if (!v || v.erased) return FF.toast('No visit for ' + code, 'bad'); B.visit = code; const want = v.picks.filter((p) => p.state === 'bag'); (want.length ? want : v.picks.filter((p) => v.shortlist.includes(p.pid))).forEach((pk) => { const p = FF.prod(pk.pid); if (p && !B.lines.some((l) => l.pid === p.id)) addLine(p, pk.size, true); }); if (!silent) { FF.closeOverlay(); FF.render(); FF.toast('Pulled in ' + B.lines.length + ' piece(s) from ' + code, 'ok'); } };
  FF.onChange('b-q', (v) => { B.q = v; const exact = FF.db.products.find((p) => p.status === 'LIVE' && (p.barcode === v.trim() || p.id.toLowerCase() === v.trim().toLowerCase())); if (exact) { addLine(exact); B.q = ''; } FF.render(); });
  FF.act('b-demo', () => { const p = FF.db.products.filter((x) => x.status === 'LIVE' && FF.stockTotal(x) > 1)[Math.floor(Math.random() * 20)]; addLine(p); FF.render(); FF.toast('Scanned ' + p.barcode, 'ok'); });
  FF.act('b-add', (d) => { addLine(FF.prod(d.pid)); B.q = ''; FF.render(); });
  FF.act('b-qty', (d) => { const l = B.lines[d.i], p = FF.prod(l.pid), n = l.qty + Number(d.d); if (n < 1) B.lines.splice(d.i, 1); else if (n > p.stock[l.size]) return FF.toast('Only ' + p.stock[l.size] + ' in stock in ' + l.size, 'bad'); else { l.disc = Math.round((l.disc / l.qty) * n); l.qty = n; } FF.render(); });
  FF.onChange('b-size', (v, el) => { const l = B.lines[el.dataset.i]; l.size = v; l.qty = Math.min(l.qty, FF.prod(l.pid).stock[v]); FF.render(); });
  FF.act('b-del', (d) => { B.lines.splice(d.i, 1); FF.render(); });
  FF.onChange('b-cust', (v, el) => { B.cust[el.dataset.k] = el.dataset.k === 'gstin' ? v.toUpperCase() : v; });
  FF.act('b-clear', () => FF.confirm('Clear this bill?', 'Nothing has been saved yet.', 'Clear', () => { B = fresh(); if (location.hash !== '#/billing') location.hash = '#/billing'; FF.render(); }));
  FF.act('b-unlink', () => { B.visit = null; B.lines.forEach((l) => { l.rec = false; }); if (location.hash !== '#/billing') location.hash = '#/billing'; FF.render(); });
  FF.act('b-hold', () => { FF.db.held.push({ at: Date.now(), b: B, by: FF.me().name }); FF.save(); B = fresh(); FF.render(); FF.toast('Bill held', 'ok'); });
  FF.act('b-recall', () => FF.modal({ title: 'Held bills', size: 'narrow', body: FF.db.held.map((h, i) => `<button class="btn btn-block mb8" style="justify-content:space-between" data-act="b-recall-go" data-i="${i}"><span>${h.b.lines.length} lines · ${FF.inr(FF.totals(h.b.lines).total)}</span><span class="small muted">${FF.fmtTime(h.at)} · ${esc(h.by)}</span></button>`).join('') }));
  FF.act('b-recall-go', (d) => { B = FF.db.held.splice(d.i, 1)[0].b; FF.save(); FF.closeOverlay(); FF.render(); });
  FF.act('b-scan', () => { const live = FF.db.visits.filter((v) => !v.erased && ['WAITING', 'ASSIGNED', 'TRYING'].includes(v.status)).slice(-6).reverse(); FF.modal({ title: "Scan the shopper's FitFirst QR", size: 'narrow', body: `<form data-submit="b-scan-go" class="col"><p class="small muted">The shopper shows the QR on their phone or the kiosk. Their chosen pieces load into the bill and the sale is linked to their visit — no typing.</p>${U.field('Or type the code', '<input name="code" required pattern="[Ff]{0,2}-?[A-Za-z0-9]{4}" placeholder="FF-7K2Q" style="font-family:var(--mono);text-transform:uppercase" data-msg="Codes look like FF-7K2Q">')}<button class="btn btn-p">Load</button></form>${live.length ? `<h4 class="mt16">On the floor now</h4><div class="row wrap mt8">${live.map((v) => `<button class="chip code" data-act="b-scan-pick" data-code="${v.code}">${v.code}</button>`).join('')}</div>` : ''}` }); });
  FF.act('b-scan-go', (f) => loadVisit('FF-' + f.code.toUpperCase().replace(/^FF-?/, '')));
  FF.act('b-scan-pick', (d) => loadVisit(d.code));
  /* discounts: bargaining is normal; above the limit a manager approves; never above MRP */
  FF.act('b-disc', (d) => { const l = B.lines[d.i]; FF.modal({ title: 'Discount · ' + esc(l.name), size: 'narrow', body: `<form data-submit="b-disc-save" class="col"><input type="hidden" name="i" value="${d.i}">${U.field('Final price for ' + l.qty + ' piece' + (l.qty > 1 ? 's' : '') + ' (₹)', `<input name="final" type="number" required min="1" max="${l.price * l.qty}" value="${l.price * l.qty - l.disc}" data-msg="Between ₹1 and ${FF.inr(l.price * l.qty)} — a piece is never sold above its price">`, `Listed at ${FF.inr(l.price * l.qty)}. Above ${FF.db.settings.billing.discLimit}% off needs a manager PIN.`)}<div class="row wrap">${[5, 10, 15, 20].map((p) => `<button type="button" class="chip" data-act="b-disc-pct" data-p="${p}" data-t="${l.price * l.qty}">${p}% off</button>`).join('')}</div><button class="btn btn-p">Apply</button></form>` }); });
  FF.act('b-disc-pct', (d) => { $('.modal input[name=final]').value = Math.round((d.t * (100 - d.p)) / 100); });
  FF.act('b-disc-save', (f) => { const l = B.lines[f.i], full = l.price * l.qty, disc = full - f.final, pct = (disc / full) * 100, apply = () => { l.disc = disc; FF.closeOverlay(); FF.render(); }; if (pct > FF.db.settings.billing.discLimit) { FF.closeOverlay(); return FF.managerPin(`${Math.round(pct)}% off ${l.name} is above the ${FF.db.settings.billing.discLimit}% limit.`, () => { l.disc = disc; FF.audit('Approved discount', l.name, Math.round(pct) + '%'); FF.save(); FF.render(); FF.toast('Discount approved', 'ok'); }); } apply(); });
  /* payment */
  FF.act('b-pay', (d) => { if (B.cust.gstin && !/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]$/.test(B.cust.gstin)) return FF.toast('That GSTIN is not valid — fix or clear it', 'bad'); if (B.cust.phone && !/^[6-9][0-9]{9}$/.test(B.cust.phone)) return FF.toast('Mobile number should be 10 digits', 'bad');
    const due = Math.max(0, FF.totals(B.lines).total - B.credit), m = d.m, upi = `upi://pay?pa=${FF.db.settings.billing.upi}&am=${due}`;
    const body = { CASH: `<form id="pf" data-submit="b-done" class="col"><input type="hidden" name="m" value="CASH">${U.field('Cash received (₹)', `<input name="cash" type="number" required min="${due}" value="${due}" data-change="b-change" data-due="${due}" data-msg="At least ${FF.inr(due)}">`)}<div class="row between"><span class="muted">Change to return</span><b class="serif" style="font-size:24px" id="b-chg">₹0</b></div></form>`,
      UPI: `<form id="pf" data-submit="b-done" class="center"><input type="hidden" name="m" value="UPI">${FF.qr(upi, 190)}<p class="serif mt8" style="font-size:26px">${FF.inr(due)}</p><p class="small muted">${esc(FF.db.settings.billing.upi)} · the exact amount is in the QR</p><label class="check mt16" style="justify-content:center"><input type="checkbox" name="ok" required data-msg="Confirm you saw the payment arrive"> <span>I have seen the payment on the shop's phone / soundbox</span></label></form>`,
      CARD: `<form id="pf" data-submit="b-done" class="col"><input type="hidden" name="m" value="CARD"><p class="small muted">Take ${FF.inr(due)} on the shop's card machine, then record the slip.</p>${U.field('Last 4 digits or approval code', '<input name="ref" required pattern="[A-Za-z0-9]{4,8}" data-msg="4 to 8 letters or digits from the slip">')}</form>`,
      SPLIT: `<form id="pf" data-submit="b-done" class="col"><input type="hidden" name="m" value="SPLIT">${U.field('Cash part (₹)', `<input name="cash" type="number" required min="1" max="${due - 1}" data-change="b-split" data-due="${due}" data-msg="Between ₹1 and ${FF.inr(due - 1)}">`)}<div class="row between"><span class="muted">Rest by UPI</span><b id="b-rest">${FF.inr(due)}</b></div><label class="check"><input type="checkbox" name="ok" required data-msg="Confirm both parts were received"> <span>Both parts received</span></label></form>` }[m];
    FF.modal({ title: { CASH: 'Cash', UPI: 'UPI payment', CARD: 'Card', SPLIT: 'Split payment' }[m] + ' · ' + FF.inr(due), size: 'narrow', body, footer: `<button class="btn" data-act="close">Back</button><button class="btn btn-p" form="pf">Complete sale</button>` }); });
  FF.onChange('b-change', (v, el) => { $('#b-chg').textContent = FF.inr(Math.max(0, v - el.dataset.due)); });
  FF.onChange('b-split', (v, el) => { $('#b-rest').textContent = FF.inr(Math.max(0, el.dataset.due - v)); });
  FF.act('b-done', (f, form) => { const tt = FF.totals(B.lines), due = Math.max(0, tt.total - B.credit); const pay = f.m === 'SPLIT' ? [{ mode: 'CASH', amt: f.cash }, { mode: 'UPI', amt: due - f.cash }] : [{ mode: f.m, amt: due, ref: f.ref || '' }]; if (B.credit) pay.push({ mode: 'CREDIT NOTE', amt: Math.min(B.credit, tt.total), ref: B.creditNo });
    const btn = $('.modal footer .btn-p'); if (btn) btn.disabled = true; const r = FF.recordSale({ source: 'BILLING', visit: B.visit, lines: B.lines, pay, doc: docType(), customer: B.cust.name || B.cust.phone || B.cust.gstin ? Object.assign({}, B.cust) : null, attribution: 'QR_SCAN' }); if (r.error) { FF.closeOverlay(); FF.render(); return FF.toast(r.error + ' — remove it from the bill', 'bad'); }
    const s = r.sale, phone = B.cust.phone, change = f.m === 'CASH' ? f.cash - due : 0; B = fresh(); FF.closeOverlay(); if (location.hash !== '#/billing') history.replaceState(null, '', '#/billing'); FF.render();
    FF.modal({ title: `Sale complete · ${s.no}`, sub: change ? `Return ${FF.inr(change)} change` : s.offline ? 'Saved on this counter — will sync when back online' : '', body: FF.receipt(s) + `<form data-submit="b-wa" class="row mt16"><input type="hidden" name="id" value="${s.id}"><input name="phone" type="tel" required pattern="[6-9][0-9]{9}" maxlength="10" placeholder="Mobile for WhatsApp e-bill" value="${esc(phone)}" data-msg="10-digit mobile number"><button class="btn">${FF.icon('wa')} Send e-bill</button></form>`, footer: `<button class="btn" data-act="print">${FF.icon('print')} Print receipt</button><button class="btn btn-p" data-act="close">New bill</button>` }); });
  FF.act('b-wa', (f) => { FF.toast('E-bill sent on WhatsApp (simulated)', 'ok'); window.open('phone.html?bill=' + f.id, '_blank'); });

  /* ---------- sales register ---------- */
  const SR = { tab: 'register', q: '', src: '', days: 7 };
  const inRange = () => FF.db.sales.filter((s) => s.at >= Date.now() - SR.days * FF.DAY);
  const SRC = { BILLING: ['FitFirst Billing', 'ok'], POS_FILE: ['Billing software file', 'info'], STAFF_APP: ['Staff app', ''] }, ATT = { QR_SCAN: 'QR scanned at billing', HANDOFF_CODE: 'Code on the bill', STAFF_LINKED: 'Linked by staff', NONE: 'Not a FitFirst sale' };
  FF.page('sales', { title: 'Sales', icon: 'book', roles: R.FLOOR, render: (open) => { const all = inRange(), rows = all.filter((s) => (!SR.src || s.source === SR.src) && (!SR.q || (s.no + ' ' + (s.visit || '')).toLowerCase().includes(SR.q.toLowerCase()))).reverse(), mgr = R.MGR.includes(FF.me().role);
    const gst = {}; all.forEach((s) => s.lines.forEach((l) => { const g = FF.gstLine(l), k = g.hsn + '|' + g.rate; (gst[k] = gst[k] || { hsn: g.hsn, rate: g.rate, taxable: 0, tax: 0, n: 0 }); gst[k].taxable += g.taxable; gst[k].tax += g.tax; gst[k].n += l.qty; }));
    const body = SR.tab === 'register' ? `<div class="filters"><input type="search" placeholder="Bill number or visit code" value="${esc(SR.q)}" data-change="sr-q" aria-label="Search bills"><select data-change="sr-src" aria-label="Source"><option value="">All sources</option>${Object.entries(SRC).map(([k, v]) => `<option value="${k}" ${SR.src === k ? 'selected' : ''}>${v[0]}</option>`).join('')}</select><span class="small muted">${rows.length} bills · ${FF.inr(FF.sum(rows, (s) => s.total))}</span></div>${U.table('sales', [{ k: 'no', l: 'Bill', html: (s) => `<span class="mono b">${esc(s.no)}</span>${s.returns.length ? ' ' + U.badge('Credit note', 'warn') : ''}` }, { k: 'at', l: 'When', sort: (s) => s.at, html: (s) => FF.fmtDT(s.at) }, { k: 'src', l: 'Source', html: (s) => U.badge(SRC[s.source][0], SRC[s.source][1]) }, { k: 'items', l: 'Items', html: (s) => `<span class="small">${esc(s.lines.map((l) => l.name).join(', ').slice(0, 44))}</span>` }, { k: 'visit', l: 'FitFirst visit', html: (s) => (s.visit ? `<span class="code small">${s.visit}</span>` : '<span class="muted">—</span>') }, { k: 'staff', l: 'Staff', html: (s) => esc(s.staff ? FF.staffName(s.staff) : '—') }, { k: 'total', l: 'Total', r: 1, sort: (s) => s.total, html: (s) => FF.inr(s.total) }], rows, { rowAct: 'sr-open', per: 12, sort: 'at', dir: -1, empty: U.empty('book', 'No bills in this view', 'Change the dates or clear the search.') })}`
      : SR.tab === 'gst' ? `<p class="small muted mb8">Tax rules are data with effective dates. Readymade garments: 5% up to ₹2,500 a piece and 18% above, decided on the price after discount. Fabric items stay at 5%. ${U.demo()}</p>${U.table('gst', [{ k: 'hsn', l: 'HSN', html: (g) => `<span class="mono">${g.hsn}</span>` }, { k: 'rate', l: 'Rate', sort: (g) => g.rate, html: (g) => g.rate + '%' }, { k: 'n', l: 'Pieces', r: 1, html: (g) => g.n }, { k: 'tx', l: 'Taxable value', r: 1, sort: (g) => g.taxable, html: (g) => FF.inr(g.taxable) }, { k: 'c', l: 'CGST', r: 1, html: (g) => FF.inr(g.tax / 2) }, { k: 's', l: 'SGST', r: 1, html: (g) => FF.inr(g.tax / 2) }, { k: 't', l: 'Total tax', r: 1, html: (g) => `<b>${FF.inr(g.tax)}</b>` }], Object.values(gst).sort((a, b) => a.hsn.localeCompare(b.hsn) || a.rate - b.rate))}<p class="note mt16 small">The shop's CA must review tax rules and bill formats before the first live bill. FitFirst does billing, not accounting — ledgers stay in Tally.</p>`
      : `<div class="grid g3">${[['gstr1', 'GSTR-1 summary', 'B2C and B2B sections by rate and HSN, as a CSV for the CA or the government offline tool.', 'CSV'], ['tally', 'Tally vouchers', 'Sales vouchers as Tally XML, so the CA keeps using Tally. The FitFirst code goes in Narration.', 'XML'], ['register', 'Sales register', 'Every bill line with staff, discount, payment mode and attribution.', 'CSV']].map(([k, t, dsc, f]) => `<div class="card col"><h3>${t}</h3><p class="small muted grow">${dsc}</p><button class="btn" data-act="sr-export" data-k="${k}">${FF.icon('download')} Download ${f}</button></div>`).join('')}</div>`;
    return `<div class="ph1"><div><h1>Sales</h1><p>One register for every sale, whichever way it was billed. Bills cannot be edited; a return or exchange creates a credit note.</p></div>${U.seg('sr-days', [[1, 'Today'], [7, '7 days'], [30, '30 days']], SR.days)}</div>${U.tabs('sr-tab', [['register', 'Register'], ['gst', 'GST summary'], ...(mgr ? [['exports', 'Exports for the CA']] : [])], SR.tab)}<div class="mt16">${body}</div>`; }, after: (open) => { if (open && !$('.drawer')) openSale(open); } });
  FF.onChange('sr-q', (v) => { SR.q = v; FF.view.sales && (FF.view.sales.page = 0); FF.render(); const i = $('.filters input[type=search]'); if (i) { i.focus(); i.setSelectionRange(v.length, v.length); } });
  FF.onChange('sr-src', (v) => { SR.src = v; FF.render(); });
  FF.act('sr-days', (d) => { SR.days = +d.v; FF.render(); }); FF.act('sr-tab', (d) => { SR.tab = d.v; FF.render(); });
  FF.act('sr-open', (d) => openSale(d.id));
  const openSale = (id) => { const s = FF.db.sales.find((x) => x.id === id); if (!s) return; const left = s.lines.some((l, i) => l.qty - FF.sum(s.returns.filter((r) => r.i === i), (r) => r.qty) > 0); FF.drawer({ title: 'Bill ' + esc(s.no), sub: `${FF.fmtDT(s.at)} · ${SRC[s.source][0]}`, body: `<dl class="kv mb16"><dt>Attribution</dt><dd>${ATT[s.attribution]}${s.visit ? ` · <a class="link code" href="#/session/${s.visit}">${s.visit}</a>` : ''}</dd><dt>Recommended items</dt><dd>${s.lines.filter((l) => l.rec).length} of ${s.lines.length}</dd><dt>Aged stock in this bill</dt><dd>${FF.inr(FF.sum(s.lines.filter((l) => l.aged), (l) => l.price * l.qty - l.disc))}${s.lines.some((l) => l.aged) ? ' · oldest ' + Math.max(...s.lines.filter((l) => l.aged).map((l) => l.age)) + ' days' : ''}</dd><dt>Staff</dt><dd>${esc(s.staff ? FF.staffName(s.staff) : '—')}</dd></dl>${FF.receipt(s)}${s.returns.length ? `<h4 class="mt16">Credit notes</h4>${s.returns.map((r) => `<div class="note n-plain mt8 small"><b class="mono">${r.no}</b> · ${esc(s.lines[r.i].name)} × ${r.qty} · ${FF.inr(r.amt)} · ${r.kind === 'EXCHANGE' ? 'exchange' : 'refund by ' + r.mode.toLowerCase()} · ${r.restock ? 'restocked' : 'not restocked (' + esc(r.why) + ')'}</div>`).join('')}` : ''}`, footer: `<button class="btn" data-act="print">${FF.icon('print')} Reprint</button>${s.source !== 'POS_FILE' && left ? `<button class="btn btn-p" data-act="sr-return" data-id="${s.id}">${FF.icon('undo')} Return or exchange</button>` : ''}` }); };
  FF.act('sr-return', (d) => { const s = FF.db.sales.find((x) => x.id === d.id), days = Math.floor((Date.now() - s.at) / FF.DAY); FF.modal({ title: 'Return or exchange · ' + esc(s.no), body: `<form id="rf" data-submit="sr-return-save" class="col"><input type="hidden" name="id" value="${s.id}">${days > 7 ? `<p class="note">This bill is ${days} days old — past the 7-day exchange window. A manager PIN will be asked.</p>` : ''}<div><div class="lbl mb8">Which piece is coming back?</div>${s.lines.map((l, i) => { const left = l.qty - FF.sum(s.returns.filter((r) => r.i === i), (r) => r.qty); return `<label class="check card mb8" style="${left ? '' : 'opacity:.5'}"><input type="radio" name="line" value="${i}" required ${left ? '' : 'disabled'} data-msg="Choose a piece"> <span><b>${esc(l.name)}</b> (${l.size}) · paid ${FF.inr((l.price * l.qty - l.disc) / l.qty)} each${left ? '' : ' · already returned'}</span></label>`; }).join('')}</div><div class="grid g2">${U.field('What does the customer want?', `<select name="kind"><option value="EXCHANGE">Exchange for something else</option><option value="REFUND">Refund</option></select>`, 'Exchange is the norm; the value carries to the new bill')}${U.field('Refund by (if refund)', `<select name="mode"><option>CASH</option><option>UPI</option></select>`)}</div>${U.field('Condition', `<select name="why"><option value="">Good — put back in stock</option><option value="Damaged">Damaged — do not restock</option><option value="Altered">Altered — do not restock</option></select>`)}</form>`, footer: `<button class="btn" data-act="close">Cancel</button><button class="btn btn-p" form="rf">Issue credit note</button>` }); });
  FF.act('sr-return-save', (f) => { const s = FF.db.sales.find((x) => x.id === f.id), i = +f.line, l = s.lines[i], run = () => { const b = FF.db.settings.billing, no = `CN/26-27/${String(b.cn++).padStart(4, '0')}`, amt = Math.round((l.price * l.qty - l.disc) / l.qty), p = FF.prod(l.pid), restock = !f.why; s.returns.push({ no, i, qty: 1, amt, kind: f.kind, mode: f.mode, restock, why: f.why, at: Date.now() }); if (restock && p) FF.moveStock(p, l.size, 1, 'RETURN', no); else if (p) FF.moveStock(p, l.size, 0, 'DAMAGE', no + ' · ' + f.why); FF.audit('Issued credit note', no, `${l.name} · ${FF.inr(amt)} · ${f.kind}`); FF.save(); FF.closeOverlay(); FF.closeOverlay();
      if (f.kind === 'EXCHANGE') { B = fresh(); B.credit = amt; B.creditNo = no; B.cust = Object.assign({ name: '', phone: '', gstin: '' }, s.customer || {}); FF.go('#/billing'); FF.toast(`${no} issued — ${FF.inr(amt)} credit is on the new bill`, 'ok'); } else { FF.render(); openSale(s.id); FF.toast(`${no} issued — refund ${FF.inr(amt)} by ${f.mode.toLowerCase()}`, 'ok'); } };
    if ((Date.now() - s.at) / FF.DAY > 7 || f.kind === 'REFUND') { FF.closeOverlay(); FF.managerPin(f.kind === 'REFUND' ? 'Refunds need a manager.' : 'Past the exchange window.', run); } else run(); });
  FF.act('sr-export', (d) => { const S = inRange(); if (!S.length) return FF.toast('No bills in this period', 'bad');
    if (d.k === 'register') return FF.download('sales-register.csv', FF.csv([['Bill', 'Date', 'Source', 'Item', 'Size', 'Qty', 'Price', 'Discount', 'GST %', 'Tax', 'Line total', 'Payment', 'Staff', 'Visit', 'Attribution']].concat(S.flatMap((s) => s.lines.map((l) => { const g = FF.gstLine(l); return [s.no, FF.day(s.at), s.source, l.name, l.size, l.qty, l.price, l.disc, g.rate, g.tax.toFixed(2), g.gross, s.pay.map((p) => p.mode).join('+'), s.staff ? FF.staffName(s.staff) : '', s.visit || '', s.attribution]; })))));
    if (d.k === 'gstr1') { const m = {}; S.forEach((s) => s.lines.forEach((l) => { const g = FF.gstLine(l), k = (s.customer && s.customer.gstin ? 'B2B|' + s.customer.gstin : 'B2CS|') + '|' + g.hsn + '|' + g.rate; (m[k] = m[k] || [0, 0]); m[k][0] += g.taxable; m[k][1] += g.tax; })); return FF.download('gstr1-summary.csv', FF.csv([['Section', 'Customer GSTIN', 'HSN', 'Rate %', 'Taxable value', 'CGST', 'SGST', 'Place of supply']].concat(Object.entries(m).map(([k, v]) => { const [sec, gstin, hsn, rate] = k.split('|'); return [sec, gstin, hsn, rate, v[0].toFixed(2), (v[1] / 2).toFixed(2), (v[1] / 2).toFixed(2), '24-Gujarat']; })))); }
    FF.download('tally-sales-vouchers.xml', `<ENVELOPE><HEADER><TALLYREQUEST>Import Data</TALLYREQUEST></HEADER><BODY><IMPORTDATA><REQUESTDATA>\n${S.filter((s) => s.source !== 'POS_FILE').map((s) => `<TALLYMESSAGE><VOUCHER VCHTYPE="Sales" ACTION="Create"><DATE>${FF.day(s.at).replace(/-/g, '')}</DATE><VOUCHERNUMBER>${s.no}</VOUCHERNUMBER><NARRATION>${s.visit ? 'FitFirst ' + s.visit : ''}</NARRATION>${s.lines.map((l) => `<ALLINVENTORYENTRIES.LIST><STOCKITEMNAME>${FF.esc(l.name)} ${l.size}</STOCKITEMNAME><ACTUALQTY>${l.qty}</ACTUALQTY><AMOUNT>${l.price * l.qty - l.disc}</AMOUNT></ALLINVENTORYENTRIES.LIST>`).join('')}</VOUCHER></TALLYMESSAGE>`).join('\n')}\n</REQUESTDATA></IMPORTDATA></BODY></ENVELOPE>`, 'application/xml'); });

  /* ---------- day close ---------- */
  const DC = { n: {}, note: '' }, NOTES = [500, 200, 100, 50, 20, 10];
  FF.page('dayclose', { title: 'Day close', icon: 'cash', roles: R.MGR, render: () => { const t0 = new Date().setHours(0, 0, 0, 0), today = FF.day(Date.now()), S = FF.db.sales.filter((s) => s.at >= t0 && s.source !== 'POS_FILE'), closed = FF.db.dayCloses.find((d) => d.date === today);
    const by = {}; S.forEach((s) => s.pay.forEach((p) => { by[p.mode] = (by[p.mode] || 0) + p.amt; })); const refunds = FF.sum(S.flatMap((s) => s.returns.filter((r) => r.kind === 'REFUND' && r.mode === 'CASH')), (r) => r.amt), float = 2000, expected = float + (by.CASH || 0) - refunds, counted = FF.sum(NOTES, (n) => n * (DC.n[n] || 0)) + (DC.n.coins || 0), any = Object.keys(DC.n).length > 0, vr = counted - expected;
    return `<div class="ph1"><div><h1>Day close</h1><p>${new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' })} · counter ${FF.db.settings.billing.series}. Count the drawer, compare with what the bills say, and file the Z-report.</p></div></div>
      ${closed ? `<div class="note n-ok mb16">Today was closed at ${FF.fmtTime(closed.at)} by ${esc(closed.by)} · variance ${closed.variance === 0 ? 'nil' : FF.inr(closed.variance)}.</div>` : ''}
      <div class="split"><div class="card"><h3>Cash in the drawer</h3><div class="grid g3 mt12">${NOTES.map((n) => U.field('₹' + n + ' notes', `<input type="number" min="0" max="999" value="${DC.n[n] ?? ''}" data-change="dc-n" data-lazy data-k="${n}" placeholder="0">`)).join('')}${U.field('Coins (₹ total)', `<input type="number" min="0" value="${DC.n.coins ?? ''}" data-change="dc-n" data-lazy data-k="coins" placeholder="0">`)}</div>
        <dl class="kv mt16" style="grid-template-columns:1fr max-content"><dt>Opening float</dt><dd class="num right">${FF.inr(float)}</dd><dt>Cash sales</dt><dd class="num right">${FF.inr(by.CASH || 0)}</dd><dt>Cash refunds</dt><dd class="num right">− ${FF.inr(refunds)}</dd><dt><b>Expected in drawer</b></dt><dd class="num right b">${FF.inr(expected)}</dd><dt><b>Counted</b></dt><dd class="num right b">${any ? FF.inr(counted) : '—'}</dd><dt><b>Difference</b></dt><dd class="num right b ${!any || vr === 0 ? 'ok' : 'bad'}">${!any ? '—' : vr === 0 ? 'Matches ✓' : (vr > 0 ? '+' : '− ') + FF.inr(Math.abs(vr))}</dd></dl>
        ${any && vr !== 0 ? `<div class="mt12">${U.field('Explain the difference', `<input data-change="dc-note" value="${esc(DC.note)}" placeholder="e.g. ₹100 given as change by mistake">`, Math.abs(vr) > 200 ? 'Required when the difference is above ₹200' : 'Optional')}</div>` : ''}<div class="row mt16"><button class="btn btn-p" data-act="dc-close" ${any && !closed ? '' : 'disabled'}>Close the day</button><button class="btn" data-act="dc-z">${FF.icon('print')} Z-report</button></div></div>
      <div class="col gap16"><div class="card"><h3>By payment mode</h3><div class="mt12">${Object.keys(by).length ? FF.chart.hbar(Object.entries(by).map(([l, v]) => ({ l, v })), FF.inr) : '<p class="small muted">No bills from this counter today yet.</p>'}</div><hr><div class="row between"><span class="muted">${S.length} bills</span><b>${FF.inr(FF.sum(S, (s) => s.total))}</b></div></div>
      <div class="card"><h3>Earlier days</h3>${FF.db.dayCloses.slice(0, 5).map((d) => `<div class="row between small" style="padding:8px 0;border-bottom:1px solid var(--line)"><span>${d.date} · ${esc(d.by)}</span><span class="${d.variance ? 'bad' : 'ok'} b">${d.variance ? FF.inr(d.variance) : 'Matched'}</span></div>`).join('') || '<p class="small muted mt8">No days closed yet in this demo.</p>'}</div></div></div>`; } });
  FF.onChange('dc-n', (v, el) => { if (v === '') delete DC.n[el.dataset.k]; else DC.n[el.dataset.k] = Math.max(0, Math.floor(Number(v) || 0)); FF.render(); });
  FF.onChange('dc-note', (v) => { DC.note = v; });
  const dcCalc = () => { const t0 = new Date().setHours(0, 0, 0, 0), S = FF.db.sales.filter((s) => s.at >= t0 && s.source !== 'POS_FILE'), by = {}; S.forEach((s) => s.pay.forEach((p) => { by[p.mode] = (by[p.mode] || 0) + p.amt; })); const refunds = FF.sum(S.flatMap((s) => s.returns.filter((r) => r.kind === 'REFUND' && r.mode === 'CASH')), (r) => r.amt); const expected = 2000 + (by.CASH || 0) - refunds, counted = FF.sum(NOTES, (n) => n * (DC.n[n] || 0)) + (DC.n.coins || 0); return { S, by, expected, counted, variance: counted - expected }; };
  FF.act('dc-close', () => { const c = dcCalc(); if (Math.abs(c.variance) > 200 && !DC.note.trim()) return FF.toast('Add a note explaining the difference', 'bad'); FF.confirm('Close the day?', `Counted ${FF.inr(c.counted)} against ${FF.inr(c.expected)} expected. This is recorded in your name.`, 'Close day', () => { FF.db.dayCloses.unshift({ date: FF.day(Date.now()), at: Date.now(), by: FF.me().name, expected: c.expected, counted: c.counted, variance: c.variance, note: DC.note, byMode: c.by }); FF.audit('Closed day', FF.day(Date.now()), 'Variance ' + FF.inr(c.variance)); FF.save(); DC.n = {}; DC.note = ''; FF.render(); FF.toast('Day closed', 'ok'); }); });
  FF.act('dc-z', () => { const c = dcCalc(), row = (a, b) => `<div class="rr"><span>${a}</span><span>${b}</span></div>`; FF.modal({ title: 'Z-report', body: `<div class="receipt printable"><div class="center"><b>${esc(FF.store().name)}</b><br>Z-REPORT · ${FF.day(Date.now())}<br>Counter ${FF.db.settings.billing.series}</div><hr>${row('Bills', c.S.length)}${row('Gross sales', FF.inr(FF.sum(c.S, (s) => s.total)))}${row('Tax collected', FF.inr(FF.sum(c.S, (s) => s.tax)))}${row('Credit notes', c.S.flatMap((s) => s.returns).length)}<hr>${Object.entries(c.by).map(([m, v]) => row(m, FF.inr(v))).join('') || row('No payments', '')}<hr>${row('Expected cash', FF.inr(c.expected))}${row('Counted cash', FF.inr(c.counted))}${row('Variance', FF.inr(c.variance))}<hr><div class="center">First bill ${c.S[0] ? c.S[0].no : '—'}<br>Last bill ${c.S.length ? c.S[c.S.length - 1].no : '—'}</div></div>`, footer: `<button class="btn btn-p" data-act="print">${FF.icon('print')} Print</button>` }); });
})();
